/* Guided, playable lessons. Shared route rules; separate learning-mode records. */
window.TryvoTutorial=(()=>{
 'use strict';
 const E=window.TryvoRescueEngine,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let host,timer,running=false,flash='',focusCell=null;
 const first={...E.levels[0],cols:5,rows:3,start:5,end:9,obstruction:7,blocked:[12],service:null,stops:[{at:6,name:'Lantern crew',people:4,fare:0,required:true}],budget:4,unit:1,carriages:1,capacity:6,minPassengers:4,optimalDistance:4,closedDistance:6,distanceLimit:4,toll:0,creditReward:0,mode:'shortcut',fares:false,profitTarget:null};
 const second={...first,cols:7,rows:3,start:7,end:13,obstruction:10,blocked:[17],stops:[{at:8,name:'Town square',people:6,fare:2},{at:1,name:'Hill stop',people:5,fare:1},{at:15,name:'Riverside',people:9,fare:1,boardingFee:2}],budget:5,unit:2,capacity:10,minPassengers:5,optimalDistance:6,closedDistance:8,distanceLimit:8,fares:true,profitTarget:0};
 const lessons=[{id:'first-connection',title:'Your first connection',subtitle:'Repair a shortcut. Bring four riders home.',time:'About 3 minutes',layout:first,phases:['intro','pickup','repair','connect','run','settle','done']},{id:'smart-service',title:'The smarter pickup',subtitle:'Compare three groups. Make the credits work.',time:'About 4 minutes',layout:second,phases:['intro','choose','budget','connect','run','settle','done']}];
 const paths={town:[7,8,9,10,11,12,13],hill:[7,0,1,2,9,10,11,12,13],river:[7,14,15,16,9,10,11,12,13]};
 const groupKeys=['town','hill','river'];
 const svg=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({tram:'<rect x="4" y="3" width="16" height="17" rx="4"/><path d="M7 7h10v6H7zM8 20l-2 3m10-3 2 3"/><circle cx="8" cy="17" r="1"/><circle cx="16" cy="17" r="1"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',flag:'<path d="M5 22V3m0 1h13l-3 4 3 4H5"/>',check:'<path d="m5 12 4 4 10-10"/>',repair:'<path d="m4 20 9-9m0-7a5 5 0 0 0 7 7l-4-2 1-4z"/>'})[name]||'<circle cx="12" cy="12" r="7"/>'}</svg>`;
 const btn=(label,action,extra='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-tutorial="${action}" ${extra}>${label}</button>`;
 function state(){const root=host.getState();if(!root.tutorial||root.tutorial.version!==1)root.tutorial={version:1,selected:lessons[0].id,drafts:{},completed:{}};return root.tutorial;}
 function newDraft(lesson){const d=E.draft(lesson.layout);d.phase='intro';d.choice=null;d.guideHidden=false;d.repairAnswer='';d.settleAnswer='';if(lesson.id==='smart-service')d.obstacle={answer:{saved:2,credits:4},solved:true,tries:[],hint:false};return d;}
 function current(){const s=state(),lesson=lessons.find(x=>x.id===s.selected)||lessons[0];let d=s.drafts[lesson.id];if(!d||!E.validatePath(lesson.layout,d.path)||!lesson.phases.includes(d.phase))d=s.drafts[lesson.id]=newDraft(lesson);return {s,lesson,l:lesson.layout,d};}
 function configure(api){host=api;}
 function cancel(){clearTimeout(timer);running=false;}
 function paint(focus){host.render(false);if(focus){const el=document.querySelector(focus);el?.focus({preventScroll:true});if(matchMedia('(max-width:900px)').matches&&(focus.includes('guide')||focus.startsWith('#tutorial-')))document.querySelector('.tutorial-guide')?.scrollIntoView({block:'start',behavior:'instant'});}}
 function say(text){flash=text;const el=document.querySelector('#tutorial-feedback');if(el)el.textContent=text;}
 function go(phase,notice=''){const {d}=current();d.phase=phase;d.guideHidden=false;flash=notice;host.save();paint('.tutorial-guide h2');}
 function art(id){return `<div class="lesson-art" aria-hidden="true"><span class="lesson-station">${svg('tram')}</span><i></i><span class="lesson-turn">${svg(id==='first-connection'?'repair':'people')}</span><i></i><span class="lesson-destination">${svg('flag')}</span></div>`;}
 function home(){const s=state();return `<section class="tutorial-home page"><div class="tutorial-intro"><div><span class="small-label">Guided demo</span><h1>Your first tram starts here.</h1><p>Learn by doing. Mira will explain each move as you make it.</p></div><span class="learning-badge">No timer. No points at stake.</span></div><div class="lesson-cards">${lessons.map((x,i)=>{const d=s.drafts[x.id],complete=s.completed[x.id],started=d&&d.phase!=='intro'&&d.phase!=='done';return `<article class="lesson-card">${art(x.id)}<div class="lesson-card-content"><span class="lesson-label">Lesson ${i+1} <span>${complete?'✓ Completed':x.time}</span></span><h2>${x.title}</h2><p>${x.subtitle}</p><ul>${(i?['Choose passengers','Understand fares and costs','Read your result']:['Connect the track','Solve an obstruction','Run and finish a journey']).map(t=>`<li>${svg('check')}${t}</li>`).join('')}</ul>${btn(started?'Continue lesson':complete?'Replay lesson':'Start lesson','start',`data-lesson="${x.id}"`)}</div></article>`;}).join('')}</div><div class="tutorial-exit"><p>Your lessons save automatically on this device. You can leave and return at any step.</p><a href="#mission-library">Extra practice: investigations</a></div>${Object.keys(s.completed).length===2?`<div class="tutorial-ready"><div><h2>Ready for the festival.</h2><p>You know how to plan, repair, compare costs and finish a journey.</p></div>${btn('Play the first journey','campaign')}</div>`:''}</section>`;}
 function target(l,d){if(d.phase==='pickup')return l.stops[0].at;if(d.phase==='repair')return l.obstruction;if(d.phase==='connect'){const route=l.cols===5?[5,6,7,8,9]:paths.town;return route[d.path.length]??null;}return null;}
 function nodeLabel(l,id){const stop=l.stops.find(x=>x.at===id);return id===l.start?'Depot':id===l.end?'Festival':id===l.obstruction?'Shortcut':stop?`${stop.people} riders`:l.blocked.includes(id)?'Closed':'Street';}
 function board(l,d){const xy=id=>[8+(id%l.cols)*84/(l.cols-1),22+Math.floor(id/l.cols)*28],poly=path=>path.map(id=>xy(id).join(',')).join(' '),t=target(l,d),open=E.obstacleOK(l,d.obstacle);let roads='';for(let a=0;a<l.cols*l.rows;a++)for(const b of [a+1,a+l.cols])if(b<l.cols*l.rows&&E.adjacent(l,a,b))roads+=`<line x1="${xy(a)[0]}" y1="${xy(a)[1]}" x2="${xy(b)[0]}" y2="${xy(b)[1]}" class="${l.blocked.includes(a)||l.blocked.includes(b)?'lesson-closed-road':''}"/>`;return `<div class="tutorial-map" role="group" aria-label="Tram practice map. Arrow keys move between streets; Enter selects."><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="tutorial-roads" aria-hidden="true">${roads}<polyline points="${poly(d.path)}" class="lesson-route"/></svg>${Array.from({length:l.cols*l.rows},(_,id)=>{const stop=l.stops.find(x=>x.at===id),type=id===l.start?'tram':id===l.end?'flag':id===l.obstruction?open?'check':'repair':stop?'people':null,[x,y]=xy(id);return `<button class="tutorial-node ${type?'is-station':''} ${d.path.includes(id)?'is-linked':''} ${id===t?'is-target':''} ${id===l.obstruction?(open?'is-repaired':'is-obstruction'):''} ${l.blocked.includes(id)?'is-closed':''}" style="left:${x}%;top:${y}%" data-tutorial="cell" data-cell-id="${id}" aria-label="${nodeLabel(l,id)}, row ${Math.floor(id/l.cols)+1}, column ${id%l.cols+1}${id===t?', next suggested action':''}" aria-pressed="${d.path.includes(id)}" tabindex="${id===(focusCell??l.start)?0:-1}" ${l.blocked.includes(id)?'aria-disabled="true"':''}>${type?svg(type):l.blocked.includes(id)?'×':'<span class="tutorial-dot"></span>'}${type?`<span class="tutorial-node-label">${nodeLabel(l,id)}</span>`:''}</button>`;}).join('')}<span class="tutorial-tram" style="left:${xy(l.start)[0]}%;top:${xy(l.start)[1]}%" hidden aria-hidden="true">${svg('tram')}</span></div>`;}
 function options(l,d){return `<div class="tutorial-fares" role="group" aria-label="Compare passenger groups">${l.stops.map((stop,i)=>{const path=paths[groupKeys[i]],cost=(path.length-1)*l.unit+(stop.boardingFee||0),fare=stop.people*stop.fare;return `<button data-tutorial="choose" data-choice="${groupKeys[i]}" aria-pressed="${d.choice===groupKeys[i]}"><strong>${stop.people} riders</strong><span>${stop.name}</span><dl><div><dt>Fares</dt><dd>${stop.people} × ${stop.fare} = ${fare}</dd></div><div><dt>Trip</dt><dd>${path.length-1} km × ${l.unit}${stop.boardingFee?' + '+stop.boardingFee+' boarding':''}</dd></div><div><dt>Total cost</dt><dd>${cost} credits</dd></div></dl><small>${d.choice===groupKeys[i]?'Selected':'Compare this pickup'}</small></button>`;}).join('')}</div>`;}
 function guide(lesson,l,d){const first=lesson.id==='first-connection';let title='',text='',action='';switch(d.phase){
 case 'intro':title=first?'Meet your tram.':'More riders isn’t always better.';text=first?'The tram starts at Depot. Four riders need to reach Festival. You have 4 travel credits; every connected street costs 1. Let’s make your first move.':'Three groups want a ride. Each kilometre costs 2 credits, and you start with 5 credits. Compare what a group pays with the cost of reaching them.';action=btn(first?'Show my first move':'Compare the groups','next');break;
 case 'pickup':title='Connect your first street.';text='Click the glowing “4 riders” stop beside Depot. You connect one kilometre of track and plan to collect the group. The credit counter updates as you build.';break;
 case 'repair':title=d.repairOpen?'Solve to open the shortcut.':'The short route is blocked.';text=d.repairOpen?'The detour is 6 km. The repaired route is 4 km. How many kilometres will you save?':'Click the striped Shortcut marker. Its small challenge unlocks the direct route. The longer detour needs 6 credits, so your budget cannot cover it.';if(d.repairOpen)action=`<form id="tutorial-repair"><label for="tutorial-saving">Kilometres saved</label><div class="tutorial-input-row"><input id="tutorial-saving" name="saving" type="number" inputmode="numeric" min="0" max="20" step="1" required value="${esc(d.repairAnswer)}" aria-describedby="tutorial-feedback"><button class="button" type="submit">Open shortcut</button></div></form>`;break;
 case 'choose':title='Which pickup pays for its trip?';text='Select a passenger group. Compare fares with total cost—not just the number of people. We need a trip where fares cover its costs.';action=btn('Check my choice','confirm-choice',d.choice?'':'disabled');break;
 case 'budget':title='Fares arrive when riders board.';text='Good choice: 6 riders pay 12 credits, and their 6 km trip costs 12. Start with 5; spend 2 reaching the stop, then collect 12. You can pay for the remaining streets.';action=btn('Build this route','next');break;
 case 'connect':title=d.path.at(-1)===l.obstruction?'Your shortcut is connected.':'Connect the route to Festival.';text=first?'Click each glowing next street, including the repaired shortcut. A solid lavender line shows your plan. Undo removes the last connection.':'Follow the direct row from Depot through the 6-rider stop to Festival. This shortcut is already repaired. Watch fares arrive at pickup and credits fall as the route grows.';break;
 case 'run':title='Your plan is ready to test.';text='Click Run tram. It follows the line you built. You can still use Undo to change your route before running it.';action=btn('Run tram','run-from-guide');break;
 case 'settle':title='Your riders arrived. Finish the trip.';text=first?'You connected 4 km at 1 credit per kilometre. Confirm the total travel cost to complete this lesson.':'You collected 12 fare credits and spent 12 on travel. What is fare income minus travel cost? This is the trip’s operating net.';action=`<form id="tutorial-settle"><label for="tutorial-total">${first?'Total travel cost':'Fares minus travel cost'} (credits)</label><div class="tutorial-input-row"><input id="tutorial-total" name="total" type="number" inputmode="numeric" min="-50" max="50" step="1" required value="${esc(d.settleAnswer)}" aria-describedby="tutorial-feedback"><button class="button" type="submit">Finish lesson</button></div></form>`;break;
 case 'done':title=first?'You made your first connection.':'You’re ready to run your own service.';text=first?'You connected streets, repaired a shortcut, tested the tram and settled its cost. Next, learn how passenger fares change a route.':'You chose the pickup using both fares and distance. In the festival, repairs and arrivals earn game points. Travel credits pay for the trip; game points determine your rank.';action=first?btn('Start lesson 2','start','data-lesson="smart-service"'):btn('Play the first journey','campaign');break;
 }const step=lesson.phases.indexOf(d.phase)+1;return `<aside class="tutorial-guide ${d.guideHidden?'guide-collapsed':''}" aria-label="Step-by-step guide"><div class="guide-person"><span>${svg(d.phase==='done'?'check':'tram')}</span><strong>${d.phase==='done'?'Lesson complete':'Mira’s guide'}</strong><button class="text-button" data-tutorial="toggle-guide" aria-expanded="${!d.guideHidden}" aria-label="${d.guideHidden?'Show':'Hide'} step guide">${d.guideHidden?'Show guide':'−'}</button></div>${d.guideHidden?'':`<p class="guide-step">Step ${step} of ${lesson.phases.length}</p><h2 tabindex="-1">${title}</h2><p>${text}</p>${action}`}<p id="tutorial-feedback" role="status" class="tutorial-feedback ${flash?'has-message':''}">${esc(flash)}</p>${d.guideHidden?'':`<div class="guide-dots" aria-label="Step ${step} of ${lesson.phases.length}">${lesson.phases.map((_,i)=>`<i class="${i<step?'complete':''}"></i>`).join('')}</div>`}</aside>`;}
 function render(){const {lesson,l,d}=current(),f=E.finance(l,d),isFirst=lesson.id==='first-connection';return `<section class="tutorial-play page"><div class="tutorial-top"><a href="#demo">← Demo lessons</a><button class="text-button" data-tutorial="restart">Restart lesson</button></div><div class="tutorial-play-title"><div><span class="small-label">Lesson ${isFirst?1:2} of 2</span><h1>${lesson.title}</h1></div><span class="learning-badge">Guided practice</span></div><div class="tutorial-workspace">${guide(lesson,l,d)}<div class="tutorial-play-area"><div class="tutorial-counters" aria-label="Live lesson budget"><div><span>Distance</span><strong>${f.distance}<small> / ${l.distanceLimit} km</small></strong></div><div><span>Riders on route</span><strong>${f.passengers}<small> / ${l.capacity} seats</small></strong></div><div><span>Credits left</span><strong class="${f.balance<0?'is-negative':''}">${f.balance}</strong></div></div>${d.phase==='choose'?options(l,d):''}<div class="tutorial-map-card">${board(l,d)}<div class="tutorial-map-footer"><div><span><i></i>Your track</span><span>${svg('repair')} Repair</span><span>× Closed</span></div><div>${btn('Undo','undo',d.path.length<=1||['intro','choose','budget','settle','done'].includes(d.phase)?'disabled':'',true)}${btn(d.phase==='done'?'Arrived ✓':'Run tram','run',d.phase!=='run'?'disabled':'')}</div></div></div><p class="tutorial-map-note">One connection = 1 km. ${l.unit} credit${l.unit===1?'':'s'} per km. <button class="text-button" data-tutorial="map-help">Map controls</button></p><details class="tutorial-calculation"><summary>Where did my credits go?</summary><p>Starting credits ${l.budget} + fares ${f.revenue} − route costs ${f.cost} = ${f.balance} credits left.</p><p>Fares appear when riders board. Connecting streets previews the budget; running the tram tests the plan.</p></details>${d.phase==='done'?`<div class="tutorial-takeaway">${svg('check')}<div><strong>${isFirst?'You know the controls.':'You know how to compare a trip.'}</strong><p>${isFirst?'Connect → repair → run → settle.':'Fares − costs = operating net. A bigger crowd can mean a worse trip.'} Tutorial practice does not add leaderboard points.</p>${!isFirst?'<a href="#progress">My progress</a> · <a href="#rankings">Rankings</a>':''}</div></div>`:''}</div></div><a class="tutorial-quit" href="#demo">Save and leave lesson</a></section>`;}
 function start(id){const s=state(),lesson=lessons.find(x=>x.id===id);if(!lesson)return;s.selected=id;if(!s.drafts[id]||s.drafts[id].phase==='done')s.drafts[id]=newDraft(lesson);flash='';focusCell=lesson.layout.start;host.save();host.navigate('#demo-play');}
 function handle(action,el){if(!host)return;if(action==='run-from-guide')action='run';if(action==='start'){start(el.dataset.lesson);return;}if(action==='campaign'){host.navigate('#explore');window.TryvoRescue.enter('first-light');return;}const {s,lesson,l,d}=current();if(running)return;
 if(action==='restart'){s.drafts[lesson.id]=newDraft(lesson);flash='Lesson restarted. Your festival progress is unchanged.';host.save();paint('.tutorial-guide h2');return;}
 if(action==='toggle-guide'){d.guideHidden=!d.guideHidden;host.save();paint('[data-tutorial="toggle-guide"]');return;}
 if(action==='next'){go(d.phase==='intro'?(lesson.id==='first-connection'?'pickup':'choose'):'connect');return;}
 if(action==='choose'){d.choice=el.dataset.choice;host.save();paint(`[data-choice="${d.choice}"]`);return;}
 if(action==='confirm-choice'){if(d.choice!=='town'){const i=groupKeys.indexOf(d.choice),stop=l.stops[i],route=paths[d.choice],cost=(route.length-1)*l.unit+(stop.boardingFee||0);say(`${stop.people} riders pay ${stop.people*stop.fare}, but this trip costs ${cost}. Compare the six-rider group: the shorter route matters.`);return;}d.boarding=Object.fromEntries(l.stops.map(x=>[x.at,x.at===8]));go('budget');return;}
 if(action==='map-help'){host.modal('Reading your route',`<div class="tutorial-help"><p><strong>Depot</strong> is your starting point. <strong>Festival</strong> is the destination.</p><p>Click a neighbouring street to extend the track. Use arrow keys and Enter if you prefer a keyboard. The glowing marker suggests your next move.</p><p>A striped shortcut opens after its challenge. A × marks a permanent closure. <strong>Undo</strong> removes the last street.</p><p>Your lesson guide stays beside the map. On a phone, it appears above the map.</p></div>`);return;}
 if(action==='undo'){if(d.path.length<=1)return;d.path.pop();d.phase=d.path.length===1&&lesson.id==='first-connection'?'pickup':lesson.id==='first-connection'&&!d.obstacle.solved?'repair':'connect';flash='Last street removed. You can try a different connection.';host.save();paint();return;}
 if(action==='cell'){const id=Number(el.dataset.cellId);focusCell=id;if(d.phase==='repair'&&id===l.obstruction){d.repairOpen=true;d.guideHidden=false;host.save();paint('#tutorial-saving');return;}if(d.phase==='pickup'&&id!==l.stops[0].at){say('Start with the glowing 4-rider stop next to Depot.');return;}if(!['pickup','connect','run'].includes(d.phase)){say(d.phase==='repair'?'Click the striped Shortcut marker to open its challenge.':'Follow the current guide before extending the route.');return;}try{const oldPhase=d.phase;if(!E.edit(l,d,id))return;const f=E.finance(l,d);flash=f.balance<0?'This route needs more credits than you have. Undo the last street.':f.distance>l.distanceLimit?'This route is too long. Undo and follow the shorter connection.':'';if(d.phase==='pickup'){d.phase=d.obstacle.solved?'connect':'repair';flash='One kilometre connected. You picked up all four riders.';}else if(d.path.at(-1)===l.end){const result=E.evaluate(l,d.path,d.puzzle,d);if(result.reason==='checkpoint')d.phase='run';else flash=result.message;}else d.phase='connect';host.save();paint(oldPhase!==d.phase?'.tutorial-guide h2':`[data-cell-id="${id}"]`);}catch(error){say(error.message);}return;}
 if(action==='run'){if(d.phase!=='run')return;const result=E.evaluate(l,d.path,d.puzzle,d);if(result.reason!=='checkpoint'){say(result.message);return;}running=true;document.querySelectorAll('.tutorial-play button').forEach(x=>x.disabled=true);const marker=document.querySelector('.tutorial-tram');marker.hidden=false;let i=0;const step=()=>{if(!document.querySelector('.tutorial-map')){cancel();return;}const id=d.path[i];marker.style.left=(8+(id%l.cols)*84/(l.cols-1))+'%';marker.style.top=(22+Math.floor(id/l.cols)*28)+'%';if(++i<d.path.length)timer=setTimeout(step,matchMedia('(prefers-reduced-motion: reduce)').matches?0:300);else{running=false;go('settle','Arrival complete. One final calculation finishes your trip.');}};say('Your tram is following the track you built…');step();}
 }
 document.addEventListener('click',e=>{const el=e.target.closest('[data-tutorial]');if(el)handle(el.dataset.tutorial,el);});
 document.addEventListener('input',e=>{if(!['tutorial-saving','tutorial-total'].includes(e.target.id)||!host)return;const {d}=current();d[e.target.id==='tutorial-saving'?'repairAnswer':'settleAnswer']=e.target.value;host.save();});
 document.addEventListener('submit',e=>{if(!['tutorial-repair','tutorial-settle'].includes(e.target.id)||!host)return;e.preventDefault();const {s,lesson,l,d}=current();if(e.target.id==='tutorial-repair'){if(Number(d.repairAnswer)!==2||d.repairAnswer===''){say('Take the repaired distance away from the detour: 6 − 4. Try again.');return;}d.obstacle={answer:{saved:2},solved:true,tries:[],hint:false};go('connect','Shortcut reopened. Your answer saves 2 km and 2 credits.');}else{const f=E.finance(l,d),expected=lesson.id==='first-connection'?f.cost:f.net;if(Number(d.settleAnswer)!==expected||d.settleAnswer===''){say(lesson.id==='first-connection'?'Multiply 4 kilometres by 1 credit per kilometre.':'Subtract 12 travel credits from 12 fare credits. Try again.');return;}s.completed[lesson.id]=true;go('done','Well done. You completed this lesson with your own route and calculation.');}});
 document.addEventListener('keydown',e=>{const el=e.target.closest('[data-cell-id]');if(!el||!host||running)return;const {l}=current(),id=Number(el.dataset.cellId),row=Math.floor(id/l.cols),col=id%l.cols;let next=id;if(e.key==='ArrowRight')next=row*l.cols+Math.min(l.cols-1,col+1);else if(e.key==='ArrowLeft')next=row*l.cols+Math.max(0,col-1);else if(e.key==='ArrowDown')next=Math.min(l.rows-1,row+1)*l.cols+col;else if(e.key==='ArrowUp')next=Math.max(0,row-1)*l.cols+col;else return;e.preventDefault();focusCell=next;document.querySelectorAll('[data-cell-id]').forEach(x=>x.tabIndex=Number(x.dataset.cellId)===next?0:-1);document.querySelector(`[data-cell-id="${next}"]`)?.focus();});
 return {configure,home,render,cancel,start};
})();
